public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (name == null || nameStart >= name.length()) {
        return;
    }
    int len = name.length();
    int current = nameStart;
    while (current < len) {
        int nextDot = name.indexOf('.', current);
        if (nextDot == -1) {
            // last component: append it entirely
            buf.append(name, current, len);
            break;
        }
        // Append abbreviation of the current component (first character)
        if (current < nextDot) {
            buf.append(name.charAt(current));
        }
        // Append the dot separator
        buf.append('.');
        // Move to the start of the next component
        current = nextDot + 1;
    }
}<|return|>

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (vertices == null || graph == null) {
        return false;
    }
    int size = vertices.size();
    if (size <= 1) {
        return true;
    }
    List<V> list = new ArrayList<>(vertices);
    for (int i = 0; i < size - 1; i++) {
        V vi = list.get(i);
        for (int j = i + 1; j < size; j++) {
            if (graph.getEdge(vi, list.get(j)) == null) {
                return false;
            }
        }
    }
    return true;
