private void pop(final String descriptor){
    int i = 0;
    if (descriptor.charAt(i) == '(') {
        i++;
        while (descriptor.charAt(i) != ')') {
            char c = descriptor.charAt(i);
            if (c == 'L') {
                i++;
                while (descriptor.charAt(i) != ';') i++;
                // reference type consumes one slot
                outputFrameStack.pop();
                i++; // skip ';'
            } else {
                // primitive type
                if (c == 'J' || c == 'D') {
                    // long/double consume two slots
                    outputFrameStack.pop();
                    outputFrameStack.pop();
                } else {
                    outputFrameStack.pop();
                }
                i++;
            }
        }
        i++; // skip ')'
    }
    // return type
    if (i < descriptor.length()) {
        char ret = descriptor.charAt(i);
        if (ret != 'V') { // not void
            if (ret == 'L') {
                i++;
                while (descriptor.charAt(i) != ';') i++;
                outputFrameStack.pop();
                i++; // skip ';'
            } else if (ret == 'J' || ret == 'D') {
                outputFrameStack.pop();
                outputFrameStack.pop();
            } else {
                outputFrameStack.pop();
            }
        }
    }
