public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> result = new ArrayList<>();
    if (file == null || !file.exists() || timeRanges == null || timeRanges.isEmpty()) {
        return result;
    }
    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            String[] parts = line.split("\\|", 2);
            if (parts.length < 2) continue;
            long ts;
            try {
                ts = Long.parseLong(parts[0]);
            } catch (NumberFormatException e) {
                continue;
            }
            boolean inRange = false;
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (ts >= range.getStart() && ts <= range.getEnd()) {
                    inRange = true;
                    break;
                }
            }
            if (!inRange) continue;
            ThreadSnapshot snapshot = new ThreadSnapshot(ts, parts[1]); // Assuming suitable constructor
            result.add(snapshot);
        }
    }
    return result;
}<|return|>
